import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

gemm_bias_relu_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

// Naive GEMM + Bias + ReLU kernel
__global__ void gemm_bias_relu_kernel(const float* __restrict__ x,
                                      const float* __restrict__ w,
                                      const float* __restrict__ bias,
                                      float* __restrict__ out,
                                      int batch_size, int in_features, int out_features) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * out_features) {
        int row = idx / out_features;
        int col = idx % out_features;

        float val = 0.0f;
        for (int k = 0; k < in_features; k++) {
            val += x[row * in_features + k] * w[col * in_features + k];
        }
        val += bias[col];
        // ReLU
        if (val < 0.0f) {
            val = 0.0f;
        }
        out[idx] = val;
    }
}

torch::Tensor gemm_bias_relu_cuda(torch::Tensor x,
                                  torch::Tensor w,
                                  torch::Tensor bias) {
    // x: [batch_size, in_features]
    // w: [out_features, in_features]
    // bias: [out_features]
    // out: [batch_size, out_features]

    const auto batch_size = x.size(0);
    const auto in_features = x.size(1);
    const auto out_features = w.size(0);

    auto out = torch::empty({batch_size, out_features}, x.options());

    int total_threads = batch_size * out_features;
    int block_size = 256;
    int grid_size = (total_threads + block_size - 1) / block_size;

    gemm_bias_relu_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        w.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        in_features,
        out_features
    );

    return out;
}
"""

gemm_bias_relu_cpp_source = (
    "torch::Tensor gemm_bias_relu_cuda(torch::Tensor x, "
    "torch::Tensor w, torch::Tensor bias);"
)

gemm_bias_relu = load_inline(
    name="gemm_bias_relu",
    cpp_sources=gemm_bias_relu_cpp_source,
    cuda_sources=gemm_bias_relu_source,
    functions=["gemm_bias_relu_cuda"],
    verbose=False,
    extra_cflags=[""],
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    """
    Optimized model that fuses matrix multiplication, adds a bias, and applies ReLU in one custom CUDA kernel.
    """
    def __init__(self, in_features, out_features, bias_shape):
        super(ModelNew, self).__init__()
        # Mimic nn.Linear(in_features, out_features, bias=False)
        self.weight = nn.Parameter(torch.randn(out_features, in_features))
        # Bias parameter
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.gemm_bias_relu = gemm_bias_relu

    def forward(self, x):
        return self.gemm_bias_relu.gemm_bias_relu_cuda(x, self.weight, self.bias)
